package nro.models.event.trungthu2026;
import java.sql.*;import java.nio.file.*;import java.io.*;import java.util.*;
import nro.models.data.LocalManager;import nro.models.player.*;import nro.models.task.*;import nro.models.services.TaskService;import nro.models.server.Manager;import nro.models.network.Message;import nro.models.consts.ConstNpc;
/** Tests recognition of existing base damage through login/task packets, never live player writes. */
public class TaskBaseDamageTest {
 static int checks;static final TaskService tasks=TaskService.gI();static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);checks++;System.out.println("PASS: "+label);}
 static class User extends TrungThuRuntimeTest.User {int nextPackets;byte[] taskPacket;User(int damage){super(1999190001);nPoint.dameg=damage;playerTask.taskMain=tasks.getTaskMainById(this,27);}@Override public void sendMessage(Message m){super.sendMessage(m);if(m.command==40)taskPacket=m.getData();if(m.command==41)nextPackets++;}}
 static void load(Connection c)throws Exception{
 try(var q=c.createStatement();var r=q.executeQuery("SELECT m.id,m.NAME,m.detail,s.NAME sub_name,s.max_count,s.notify,s.npc_id,s.map FROM task_main_template m JOIN task_sub_template s ON s.task_main_id=m.id ORDER BY m.id,s.ducvupro")){TaskMain main=null;while(r.next()){if(main==null||main.id!=r.getInt("id")){main=new TaskMain();main.id=r.getInt("id");main.name=r.getString("NAME");main.detail=r.getString("detail");Manager.TASKS.add(main);}var sub=new SubTaskMain();sub.name=r.getString("sub_name");sub.maxCount=r.getShort("max_count");sub.notify=r.getString("notify");sub.npcId=r.getByte("npc_id");sub.mapId=r.getShort("map");main.subTasks.add(sub);}}
 }
 public static void main(String[] args)throws Exception{try(Connection c=LocalManager.getConnection()){
 check("nro_panel_qa_20261013".equals(c.getCatalog()),"QA guard");try(var q=c.createStatement()){for(String t:List.of("task_main_template","task_sub_template")){q.execute("CREATE TABLE IF NOT EXISTS "+t+" LIKE srcnrofree."+t);q.executeUpdate("DELETE FROM "+t);q.executeUpdate("INSERT INTO "+t+" SELECT * FROM srcnrofree."+t);}}
 String sql=Files.readString(Path.of(args[0],"web/task_schema.sql"));for(int i=0;i<2;i++)try(var q=c.createStatement()){for(String part:sql.split(";"))if(!part.isBlank())q.execute(part);}load(c);User data=new User(0);check(data.playerTask.taskMain.subTasks.get(0).name.contains("10K")&&data.playerTask.taskMain.subTasks.get(0).notify.contains("10K"),"mission label and hint agree on ten thousand");
 User low=new User(9999);low.nPoint.dame=1000000000;tasks.sendTaskMain(low);check(low.playerTask.taskMain.index==0&&low.nextPackets==0,"equipment/total damage cannot replace insufficient base damage");
 for(int amount:new int[]{10000,22000,35000}){User p=new User(amount);long gold=p.inventory.gold,tn=p.nPoint.tiemNang;tasks.sendTaskMain(p);check(p.playerTask.taskMain.index==1&&p.nextPackets==1,"login recognizes already-trained base damage "+amount);check(p.playerTask.taskMain.subTasks.get(1).count==0&&p.inventory.gold==gold&&p.nPoint.tiemNang==tn,"only stat step advances; later objectives and rewards preserved");tasks.sendTaskMain(p);tasks.checkDoneTaskNangCS(p);check(p.playerTask.taskMain.index==1&&p.nextPackets==1,"repeat refresh does not advance again");}
 User entering=new User(22000);entering.playerTask.taskMain=tasks.getTaskMainById(entering,26);tasks.sendNextTaskMain(entering);check(entering.playerTask.taskMain.id==27&&entering.playerTask.taskMain.index==1,"receiving mission after training immediately recognizes completion");
 User pending=new User(9999);pending.nPoint.limitPower=5;pending.nPoint.tiemNang=1000000;pending.nPoint.increasePoint((byte)2,(short)1);check(pending.nPoint.dameg==10000&&pending.playerTask.taskMain.index==1,"normal stat spending still completes at exact threshold");
 User next=new User(22000);next.playerTask.taskMain.index=1;next.playerTask.taskMain.subTasks.get(1).count=17;tasks.sendTaskMain(next);check(next.playerTask.taskMain.index==1&&next.playerTask.taskMain.subTasks.get(1).count==17,"existing capsule progress is preserved");
 User other=new User(1000000);other.playerTask.taskMain=tasks.getTaskMainById(other,26);tasks.sendTaskMain(other);check(other.playerTask.taskMain.id==26&&other.playerTask.taskMain.index==0,"unrelated task cannot be skipped");
 for(int kind=0;kind<4;kind++){User p=new User(35000);p.isPet=kind==0;p.isBoss=kind==1;p.isBot=kind==2;p.isNewPet=kind==3;tasks.checkDoneTaskNangCS(p);check(p.playerTask.taskMain.index==0,"non-player entity excluded "+kind);}
 var karin=new nro.models.npc_list.QuocVuong(0,1,0,0,ConstNpc.THAN_MEO_KARIN,0);check(!tasks.checkDoneTaskTalkNpc(low,karin)&&low.playerTask.taskMain.index==0,"talking to Karin cannot bypass ten thousand requirement");
 tasks.checkDoneTaskNangCS(null);User empty=new User(35000);empty.playerTask.taskMain=null;tasks.checkDoneTaskNangCS(empty);check(empty.playerTask.taskMain==null,"missing task data handled without mutation");
 System.out.println("PASS: "+checks+" base damage mission checks; QA only");
 }catch(Throwable e){e.printStackTrace();System.exit(1);}finally{LocalManager.close();}System.exit(0);}
}